@Test
void deviceRestListsOnlyPublicMetadataAndRevokesPairing() throws Exception {
    var provider = new ScriptedModelProvider();
    PermissionBroker permissions = new PermissionBroker(Clock.systemUTC());
    var hostStore = new MemoryHostStore();
    var tokens = new LocalTokenService(new SecureRandom(), Clock.systemUTC());
    var devices = new io.github.diodeme.ji.host.HostDeviceRegistry("local-host", tokens);
    byte[] deviceKey = new byte[32];
    java.util.Arrays.fill(deviceKey, (byte) 4);
    devices.pair("install-1", tokens.issue(), "desktop-1", deviceKey);
    var project = new io.github.diodeme.ji.extension.ProjectTrustStore.ProjectIdentity(
            "project-1", "/workspace");
    var resourceService = new io.github.diodeme.ji.host.ResourceApplicationService(
            project, new TestProjectTrustStore(), () -> resourceSnapshot("ready"),
            ignored -> resourceSnapshot("ready"), Clock.systemUTC());
    try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionRepository(hostStore)
            .permissionDecider(permissions).build();
         var sessions = new SessionApplicationService(runtime);
         var server = new LocalHostServer(sessions, permissions,
                 new PromptApplicationService(sessions, hostStore), new ModelRef("faux", "faux-1"),
                 tokens, 0, 0, new io.github.diodeme.ji.artifact.fs.FileArtifactStore(
                         java.nio.file.Files.createTempDirectory("ji-device-rest-artifacts-"),
                         io.github.diodeme.ji.artifact.ArtifactLimits.defaults()),
                 new ProviderProfileApplicationService(new MemoryProviderProfileStore(), hostStore),
                 resourceService, devices)) {
        var cookies = new CookieManager(null, CookiePolicy.ACCEPT_ALL);
        HttpClient client = HttpClient.newBuilder().cookieHandler(cookies).build();
        URI root = URI.create("http://127.0.0.1:" + server.port());
        assertEquals(200, post(client, root.resolve("/api/v1/auth/local/exchange"),
                "{\"token\":\"" + server.issueLaunchToken() + "\"}").statusCode());
        JsonNode listed = json(client.send(HttpRequest.newBuilder(root.resolve("/api/v1/devices"))
                .GET().build(), HttpResponse.BodyHandlers.ofString()));
        assertEquals("desktop-1", listed.path("devices").get(0).path("deviceId").asText());
        assertEquals("host-admin", listed.path("devices").get(0).path("role").asText());
        assertFalse(listed.toString().contains("publicKey"));
        HttpResponse<String> revoked = client.send(HttpRequest.newBuilder(root.resolve(
                "/api/v1/devices/desktop-1")).DELETE().build(), HttpResponse.BodyHandlers.ofString());
        assertEquals(200, revoked.statusCode());
        assertTrue(devices.device("desktop-1").isEmpty());
    }
}

